<template><div class="toolbar"><button v-if="admin" class="primary" @click="registering=!registering">注册服务器</button></div><RegisterNodeForm v-if="registering" @saved="registering=false" @cancel="registering=false"/><PanelCard title="服务器与执行器" description="主机失联时展示未知状态，不使用历史成功记录替代实时状态。"><DataTable :rows="rows" :columns="columns"><template #name="{row}"><RouterLink :to="'/hosts/'+row.id">{{row.name}}</RouterLink><small>{{row.url}}</small></template><template #status="{row}"><StateBadge :status="row.online?'healthy':'UNKNOWN'"/></template><template #memory="{row}">{{bytes(row.data?.node?.MemTotal)}}</template><template #docker="{row}">{{row.data?.node?.ServerVersion||'不可达'}}</template></DataTable></PanelCard><template v-if="selected"><PanelCard :title="selected.name+' · 资源监控'"><HostMetrics :key="selected.id" :node="selected.id"/></PanelCard><PanelCard title="运行环境"><dl class="facts"><dt>执行器</dt><dd>{{selected.url}}</dd><dt>Docker 服务</dt><dd>{{selected.data?.node?.ServerVersion||'当前不可达'}}</dd><dt>CPU 核数</dt><dd>{{selected.data?.node?.NCPU??'未知'}}</dd><dt>Docker 数据根目录</dt><dd>{{selected.data?.node?.DockerRootDir||'未知'}}</dd></dl></PanelCard></template></template>
<script setup>
import {computed,ref} from 'vue';import {useSession} from '../../stores/session';import RegisterNodeForm from '../../components/hosts/RegisterNodeForm.vue';import {useRoute} from 'vue-router';import {useCluster} from '../../stores/cluster';import {bytes} from '../../utils/format';import PanelCard from '../../components/ui/PanelCard.vue';import DataTable from '../../components/ui/DataTable.vue';import StateBadge from '../../components/ui/StateBadge.vue';import HostMetrics from '../../components/metrics/HostMetrics.vue';
const {admin}=useSession(),registering=ref(false),route=useRoute(),{nodes,inventory}=useCluster(),rows=computed(()=>nodes.value.map(node=>{const snapshot=inventory.value.find(n=>n.id===node.id);return {...node,...snapshot,online:!!snapshot?.data};})),selected=computed(()=>rows.value.find(n=>String(n.id)===route.params.node)||(!route.params.node?rows.value[0]:null));const columns=[{key:'name',label:'服务器'},{key:'status',label:'连接状态'},{key:'docker',label:'Docker 版本'},{key:'memory',label:'主机内存'}];
</script>
